package com.steadyme.app.ui;
import android.content.*;import android.os.Bundle;import android.view.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import com.steadyme.app.CameraLogActivity;import com.steadyme.app.databinding.FragmentLogOptionsBinding;
public class LogOptionsFragment extends Fragment{private FragmentLogOptionsBinding binding;@Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){binding=FragmentLogOptionsBinding.inflate(i,c,false);return binding.getRoot();}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){binding.cardManual.setOnClickListener(x->getParentFragmentManager().beginTransaction().replace(com.steadyme.app.R.id.fragmentContainer,new ManualLogFragment()).addToBackStack(null).commit());binding.cardCamera.setOnClickListener(x->startActivity(new Intent(requireContext(),CameraLogActivity.class)));}@Override public void onDestroyView(){binding=null;super.onDestroyView();}}
